#include <bits/stdc++.h>
using namespace std;

long long get_v(int x, int k, const vector<long long>&  P, int n){
    return 2LL *P[x] + P[2* k -x]+ 3LL * P[3*n -k -x];
}

long long get_d(int x, int k, const vector<long long>& A, int n){
    return 2LL * A[x +1] - A[2 * k - x] - 3LL * A[3 * n - k - x];
}


void corr(){
    int n;
    cin>>n;
    int ns = 3 * n;
    vector<long long> A(ns +1);
    for(int  i= 1; i <= ns;++i){
        cin>>A[i];
    }
    sort(A.begin()+1,A.end(),greater<long long>());
    vector <long long> P(ns +1, 0);
    for( int i = 1; i <= ns; ++i){
        P[i]  = P [ i -1 ] + A[i];
    }
    long long ms = 0;
    for(int k = 0 ; k <= n; ++k){
        int low = 0, high = k -1;
        int best_x = k;
        while(low <=high ){
            int mid = low + (high- low) /2;
        
            if(get_d(mid, k, A, n) <= 0){
                best_x = mid;
                high = mid -1;
            }
            else {
                low = mid+1;
            }
        }
        
        long long cmax = get_v(best_x, k, P , n);
        if(best_x -1 >= 0){
            cmax = max(cmax, get_v(best_x -1, k, P , n));
        }
        if(best_x + 1 <= k){
            cmax = max(cmax, get_v(best_x +1, k , P, n));
        }
        ms = max(ms, cmax);
    }
    cout<<ms<<"\n";
}
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n;
    if(cin>>n){
        while(n--){
            corr();
        }
    }
    return 0;
}
